ALTER TABLE "anchor_contact_endpoints" ADD CONSTRAINT "anchor_contact_endpoints_verification_expiry_check" CHECK ("anchor_contact_endpoints"."verification_expires_at" IS NULL OR ("anchor_contact_endpoints"."verified_at" IS NOT NULL AND "anchor_contact_endpoints"."verification_expires_at" > "anchor_contact_endpoints"."verified_at"));--> statement-breakpoint
ALTER TABLE "anchor_contact_endpoints" ADD CONSTRAINT "anchor_contact_endpoints_revoked_check" CHECK ("anchor_contact_endpoints"."revoked_at" IS NULL OR ("anchor_contact_endpoints"."verified_at" IS NOT NULL AND "anchor_contact_endpoints"."revoked_at" >= "anchor_contact_endpoints"."verified_at"));